class Solution {
 public:
  long long findKthSmallest(vector<int>& coins, int k) {
    const vector<vector<long>> sizeToLcms = getSizeToLcms(coins);
    long l = 0;
    long r = static_cast<long>(k) * ranges::min(coins);

    while (l < r) {
      const long m = (l + r) / 2;
      if (numDenominationsNoGreaterThan(sizeToLcms, m) >= k)
        r = m;
      else
        l = m + 1;
    }

    return l;
  }

 private:
  // Returns the number of denominations <= m.
  long numDenominationsNoGreaterThan(const vector<vector<long>>& sizeToLcms,
                                     long m) {
    long res = 0;
    for (int sz = 1; sz < sizeToLcms.size(); ++sz)
      for (const long lcm : sizeToLcms[sz])
        // Principle of Inclusion-Exclusion (PIE)
        res += m / lcm * pow(-1, sz + 1);
    return res;
  };

  // Returns the LCMs for each number of combination of coins.
  vector<vector<long>> getSizeToLcms(const vector<int>& coins) {
    const int n = coins.size();
    const int maxMask = 1 << n;
    vector<vector<long>> sizeToLcms(n + 1);

    for (unsigned mask = 1; mask < maxMask; ++mask) {
      long lcmOfSelectedCoins = 1;
      for (int i = 0; i < n; ++i)
        if (mask >> i & 1)
          lcmOfSelectedCoins = lcm(lcmOfSelectedCoins, coins[i]);
      sizeToLcms[popcount(mask)].push_back(lcmOfSelectedCoins);
    }

    return sizeToLcms;
  }
};

class Solution {
 public:
  vector<int> remainingMethods(int n, int k, vector<vector<int>>& invocations) {
    vector<int> ans;
    vector<vector<int>> graph(n);

    for (const vector<int>& invocation : invocations) {
      const int u = invocation[0];
      const int v = invocation[1];
      graph[u].push_back(v);
    }

    queue<int> q{{k}};
    vector<bool> seen(n);
    seen[k] = true;

    while (!q.empty())
      for (int sz = q.size(); sz > 0; --sz) {
        const int u = q.front();
        q.pop();
        for (const int v : graph[u])
          if (!seen[v]) {
            q.push(v);
            seen[v] = true;
          }
      }

    for (int u = 0; u < n; ++u) {
      if (seen[u])
        continue;
      for (const int v : graph[u])
        if (seen[v]) {
          ans.resize(n);
          iota(ans.begin(), ans.end(), 0);
          return ans;
        }
      ans.push_back(u);
    }

    return ans;
  }
};

class Solution {
 public:
  vector<int> gcdValues(vector<int>& nums, vector<long long>& queries) {
    const int maxNum = ranges::max(nums);
    vector<int> ans;
    // countDivisor[d] := the number of `nums` having `num % d == 0`
    vector<int> countDivisor(maxNum + 1);
    // countGcdPair[g] := the number of pairs having gcd == g
    vector<long> countGcdPair(maxNum + 1);
    // prefixCountGcdPair[g] := the number of pairs having gcd <= g
    vector<long> prefixCountGcdPair{0};

    for (const int num : nums)
      for (int i = 1; i * i <= num; ++i)
        if (num % i == 0) {
          ++countDivisor[i];
          if (i != num / i)
            ++countDivisor[num / i];
        }

    for (int gcd = maxNum; gcd >= 1; --gcd) {
      // There are C(countDivisor[gcd], 2) pairs that have a common divisor
      // that's a multiple of `gcd` (including the one that equals to `gcd`).
      // So, substract the multiples of `gcd` to have the number of pairs with a
      // gcd that's exactly `gcd`.
      countGcdPair[gcd] =
          countDivisor[gcd] * static_cast<long>(countDivisor[gcd] - 1) / 2;
      for (int largerGcd = 2 * gcd; largerGcd <= maxNum; largerGcd += gcd)
        countGcdPair[gcd] -= countGcdPair[largerGcd];
    }

    for (int gcd = 1; gcd <= maxNum; ++gcd)
      prefixCountGcdPair.push_back(prefixCountGcdPair.back() +
                                   countGcdPair[gcd]);

    for (const long query : queries)
      ans.push_back(getNthGcdPair(query, prefixCountGcdPair));

    return ans;
  }
  private:
  // Returns the `query`-th gcd pair.
  int getNthGcdPair(long query, const vector<long>& prefixCountGcdPair) {
    int l = 1;
    int r = prefixCountGcdPair.size() - 1;
    while (l < r) {
      const int m = (l + r) / 2;
      if (prefixCountGcdPair[m] < query + 1)
        l = m + 1;
      else
        r = m;
    }
    return l;
  }
};

class Solution {
 public:
  vector<int> validSequence(string word1, string word2) {
    vector<int> ans(word2.length());
    // last[j] := the index i of the last occurrence in word1, where
    // word1[i] == word2[j]
    vector<int> last(word2.length(), -1);

    int i = word1.length() - 1;
    int j = word2.length() - 1;
    while (i >= 0 && j >= 0) {
      if (word1[i] == word2[j])
        last[j--] = i;
      --i;
    }

    bool canSkip = true;
    j = 0;
    for (i = 0; i < word1.length(); ++i) {
      if (j == word2.length())
        break;
      if (word1[i] == word2[j]) {
        ans[j++] = i;
      } else if (canSkip && (j == word2.length() - 1 || i < last[j + 1])) {
        canSkip = false;
        ans[j++] = i;
      }
    }

    return j == word2.length() ? ans : vector<int>();
  }
};

class Solution {
 public:
  int subsequencePairCount(vector<int>& nums) {
    const int maxNum = ranges::max(nums);
    vector<vector<vector<int>>> mem(
        nums.size(),
        vector<vector<int>>(maxNum + 1, vector<int>(maxNum + 1, -1)));
    return subsequencePairCount(nums, 0, 0, 0, mem);
  }

 private:
  static constexpr int kMod = 1'000'000'007;

  // Returns the number of disjoint pairs `seq1` and `seq2` of nums[i..n - 1],
  // where GCD(seq1) == x and GCD(seq2) == y.
  int subsequencePairCount(const vector<int>& nums, int i, int x, int y,
                           vector<vector<vector<int>>>& mem) {
    if (i == nums.size())
      return x > 0 && x == y;
    if (mem[i][x][y] != -1)
      return mem[i][x][y];
    // 1. Skip nums[i].
    const int skip = subsequencePairCount(nums, i + 1, x, y, mem);
    // 2. Pick nums[i] in the first subsequence.
    const int take1 =
        subsequencePairCount(nums, i + 1, gcd(x, nums[i]), y, mem);
    // 3. Pick nums[i] in the second subsequence.
    const int take2 =
        subsequencePairCount(nums, i + 1, x, gcd(y, nums[i]), mem);
    return mem[i][x][y] = (static_cast<long>(skip) + take1 + take2) % kMod;
  }
};

class Solution {
 public:
  int smallestNumber(int n, int t) {
    for (int num = n; num < n + 10; ++num)
      if (getDigitProd(num) % t == 0)
        return num;
    throw;
  }

 private:
  int getDigitProd(int num) {
    int digitProd = 1;
    while (num > 0) {
      digitProd *= num % 10;
      num /= 10;
    }
    return digitProd;
  }
};

class Solution {
  public String smallestNumber(String num, long t) {
    Pair<Map<Integer, Integer>, Boolean> primeCountResult = getPrimeCount(t);
    Map<Integer, Integer> primeCount = primeCountResult.getKey();
    boolean isDivisible = primeCountResult.getValue();
    if (!isDivisible)
      return "-1";

    Map<Integer, Integer> factorCount = getFactorCount(primeCount);
    if (sumValues(factorCount) > num.length())
      return construct(factorCount);

    Map<Integer, Integer> primeCountPrefix = getPrimeCount(num);
    int firstZeroIndex = num.indexOf('0');
    if (firstZeroIndex == -1) {
      firstZeroIndex = num.length();
      if (isSubset(primeCount, primeCountPrefix))
        return num;
    }

    for (int i = num.length() - 1; i >= 0; --i) {
      final int d = num.charAt(i) - '0';
      // Remove the current digit's factors from primeCountPrefix.
      primeCountPrefix = subtract(primeCountPrefix, FACTOR_COUNTS.get(d));
      final int spaceAfterThisDigit = num.length() - 1 - i;
      if (i > firstZeroIndex)
        continue;
      for (int biggerDigit = d + 1; biggerDigit < 10; ++biggerDigit) {
        // Compute the required factors after replacing with a larger digit.
        Map<Integer, Integer> factorsAfterReplacement = getFactorCount(
            subtract(subtract(primeCount, primeCountPrefix), FACTOR_COUNTS.get(biggerDigit)));
        // Check if the replacement is possible within the available space.
        if (sumValues(factorsAfterReplacement) <= spaceAfterThisDigit) {
          // Fill extra space with '1', if any, and construct the result.
          final int fillOnes = spaceAfterThisDigit - sumValues(factorsAfterReplacement);
          return num.substring(0, i) + // Keep the prefix unchanged.
              biggerDigit +            // Replace the current digit.
              "1".repeat(fillOnes) + // Fill remaining space with '1'.
              construct(factorsAfterReplacement);
        }
      }
    }

    // No solution of the same length exists, so we need to extend the number
    // by prepending '1's and adding the required factors.
    Map<Integer, Integer> factorsAfterExtension = getFactorCount(primeCount);
    return "1".repeat(num.length() + 1 - sumValues(factorsAfterExtension)) +
        construct(factorsAfterExtension);
  }

  private static final Map<Integer, Map<Integer, Integer>> FACTOR_COUNTS = Map.of(
      0, Map.of(), 1, Map.of(), 2, Map.of(2, 1), 3, Map.of(3, 1), 4, Map.of(2, 2), 5, Map.of(5, 1),
      6, Map.of(2, 1, 3, 1), 7, Map.of(7, 1), 8, Map.of(2, 3), 9, Map.of(3, 2));

  // Returns the prime count of t and if t is divisible by 2, 3, 5, 7.
  private Pair<Map<Integer, Integer>, Boolean> getPrimeCount(long t) {
    Map<Integer, Integer> count = new HashMap<>(Map.of(2, 0, 3, 0, 5, 0, 7, 0));
    for (int prime : new int[] {2, 3, 5, 7}) {
      while (t % prime == 0) {
        t /= prime;
        count.put(prime, count.get(prime) + 1);
      }
    }
    return new Pair<>(count, t == 1);
  }

  // Returns the prime count of `num`.
  private Map<Integer, Integer> getPrimeCount(String num) {
    Map<Integer, Integer> count = new HashMap<>(Map.of(2, 0, 3, 0, 5, 0, 7, 0));
    for (final char c : num.toCharArray()) {
      Map<Integer, Integer> digitFactors = FACTOR_COUNTS.get(c - '0');
      for (Map.Entry<Integer, Integer> entry : digitFactors.entrySet()) {
        final int prime = entry.getKey();
        final int freq = entry.getValue();
        count.merge(prime, freq, Integer::sum);
      }
    }
    return count;
  }

  private Map<Integer, Integer> getFactorCount(Map<Integer, Integer> count) {
    // 2^3 = 8
    final int count8 = count.get(2) / 3;
    final int remaining2 = count.get(2) % 3;
    // 3^2 = 9
    final int count9 = count.get(3) / 2;
    int count3 = count.get(3) % 2;
    // 2^2 = 4
    int count4 = remaining2 / 2;
    int count2 = remaining2 % 2;
    // Combine 2 and 3 to 6 if both are present
    int count6 = 0;
    if (count2 == 1 && count3 == 1) {
      count2 = 0;
      count3 = 0;
      count6 = 1;
    }
    // Combine 3 and 4 to 2 and 6 if both are present
    if (count3 == 1 && count4 == 1) {
      count2 = 1;
      count6 = 1;
      count3 = 0;
      count4 = 0;
    }
    return Map.of(2, count2, 3, count3, 4, count4, 5, count.get(5), 6, count6, 7, count.get(7), 8,
                  count8, 9, count9);
  }

  private String construct(Map<Integer, Integer> factors) {
    StringBuilder sb = new StringBuilder();
    for (int digit = 2; digit < 10; ++digit)
      sb.append(String.valueOf(digit).repeat(factors.get(digit)));
    return sb.toString();
  }

  // Returns true if a is a subset of b.
  private boolean isSubset(Map<Integer, Integer> a, Map<Integer, Integer> b) {
    for (Map.Entry<Integer, Integer> entry : a.entrySet())
      if (b.get(entry.getKey()) < entry.getValue())
        return false;
    return true;
  }

  // Returns a - b.
  private Map<Integer, Integer> subtract(Map<Integer, Integer> a, Map<Integer, Integer> b) {
    Map<Integer, Integer> res = new HashMap<>(a);
    for (Map.Entry<Integer, Integer> entry : b.entrySet()) {
      final int key = entry.getKey();
      final int value = entry.getValue();
      res.put(key, Math.max(0, res.get(key) - value));
    }
    return res;
  }

  // Returns the sum of the values in `count`.
  private int sumValues(Map<Integer, Integer> count) {
    return count.values().stream().mapToInt(Integer::intValue).sum();
  }
}

class Solution {
 public:
  int largestInteger(vector<int>& nums, int k) {
    if (k == nums.size())
      return ranges::max(nums);
    const vector<int> count = getCount(nums);
    if (k == 1)
      return maxUnique(nums, count);
    return max(count[nums.front()] == 1 ? nums.front() : -1,
               count[nums.back()] == 1 ? nums.back() : -1);
  }

 private:
  // Returns the maximum unique integer in nums if any. Otherwise, returns -1.
  int maxUnique(const vector<int>& nums, const vector<int>& count) {
    int maxUnique = -1;
    for (const int num : nums)
      if (count[num] == 1)
        maxUnique = max(maxUnique, num);
    return maxUnique;
  }

  vector<int> getCount(const vector<int>& nums) {
    constexpr int kMax = 50;
    vector<int> count(kMax + 1);
    for (const int num : nums)
      ++count[num];
    return count;
  }
};

