class Solution {
public:
    bool uniformArray(vector<int>& nums1) {
        long long minOdd = LLONG_MAX;
        
        for (int x : nums1) {
            if (x & 1) minOdd = min(minOdd, (long long)x);
        }

        auto canMake = [&](int targetParity) {
            for (int x : nums1) {
                int p = x & 1;

                if (p == targetParity) continue; // use nums1[i] itself

                // To flip parity, we need an odd number smaller than x.
                if (minOdd == LLONG_MAX || minOdd >= x)
                    return false;
            }
            return true;
        };

        return canMake(0) || canMake(1);
    }
};

class Solution {
public:
    int firstStableIndex(vector<int>& nums, int k) {
        int n = nums.size();

        vector<long long> prefixMax(n), suffixMin(n);

        prefixMax[0] = nums[0];
        for (int i = 1; i < n; i++) {
            prefixMax[i] = max(prefixMax[i - 1], (long long)nums[i]);
        }

        suffixMin[n - 1] = nums[n - 1];
        for (int i = n - 2; i >= 0; i--) {
            suffixMin[i] = min(suffixMin[i + 1], (long long)nums[i]);
        }

        for (int i = 0; i < n; i++) {
            if (prefixMax[i] - suffixMin[i] <= k) {
                return i;
            }
        }

        return -1;
    }
};

class Solution {
public:
    int firstStableIndex(vector<int>& nums, int k) {
        int n = nums.size();

        vector<long long> sufMin(n);
        sufMin[n - 1] = nums[n - 1];

        for (int i = n - 2; i >= 0; --i) {
            sufMin[i] = min(sufMin[i + 1], (long long)nums[i]);
        }

        long long prefMax = 0;

        for (int i = 0; i < n; ++i) {
            prefMax = max(prefMax, (long long)nums[i]);

            if (prefMax - sufMin[i] <= k) {
                return i;
            }
        }

        return -1;
    }
};
